 * @param {Object} viewModel - A KnockoutJS-style ViewModel object
 * @returns {Object} A debug helper object with diagnoseMissingProperty method
 */
function createDebugHelper(viewModel) {
  // Get sorted list of available properties
  const availableProperties = Object.keys(viewModel).sort();

  return {
    /**
     * Diagnose a missing property binding error.
     * @param {string} propertyName - The property name that failed to bind
     * @returns {Object} An error object with diagnosis details
     */
    diagnoseMissingProperty(propertyName) {
      const isAvailable = availableProperties.includes(propertyName);

      if (isAvailable) {
        return {
          error: false,
          missingProperty: propertyName,
          availableProperties: availableProperties,
          suggestion: null
        };
      }

      // Find the closest matching property
      let bestMatch = null;
      let bestDistance = Infinity;

      for (const prop of availableProperties) {
        const dist = levenshteinDistance(propertyName, prop);
        if (dist <= 3) {
          if (dist < bestDistance || (dist === bestDistance && prop < bestMatch)) {
            bestDistance = dist;
            bestMatch = prop;
          }
        }
      }

      return {
        error: true,
        missingProperty: propertyName,
        availableProperties: availableProperties,
        suggestion: bestMatch
      };
    }
  };
}

module.exports = {
  createDebugHelper,
  diagnoseMissingProperty: null // Will be set by createDebugHelper
};"}

